/* Basic selectors */
* { box-sizing: border-box; }
body { margin: 0; padding: 0; font-family: sans-serif; }
h1, h2, h3, h4, h5, h6 { font-weight: bold; }

/* Classes and IDs */
.container { width: 100%; max-width: 1200px; margin: 0 auto; }
#header { background: linear-gradient(to right, #ff0000, #00ff00); }

/* Pseudo-classes and pseudo-elements */
a:link { color: blue; }
a:visited { color: purple; }
a:hover { color: red; text-decoration: underline; }
a:active { color: orange; }
p::first-letter { font-size: 2em; float: left; }
p::first-line { font-weight: bold; }
.button::before { content: "→ "; }
.button::after { content: " ←"; }
input:focus { outline: 2px solid blue; box-shadow: 0 0 5px rgba(0,0,255,0.5); }
input:checked + label { font-weight: bold; }
input:disabled { opacity: 0.5; cursor: not-allowed; }

/* Combinators */
div p { color: inherit; }
div > p { margin: 0; }
h1 + p { margin-top: 0; }
h1 ~ p { color: gray; }

/* Attribute selectors */
[data-active] { color: green; }
[data-state="loading"] { opacity: 0.7; }
[href^="https"] { color: green; }
[href$=".pdf"] { background: url(pdf-icon.png) no-repeat; }
[href*="example"] { text-decoration: none; }
[lang|="en"] { quotes: '"' '"'; }

/* Box model */
.box {
    width: 300px;
    height: 200px;
    padding: 20px 15px 10px 5px;
    margin: 10px auto;
    border: 2px solid #000;
    border-radius: 10px 20px 30px 40px;
    box-shadow: 0 4px 6px rgba(0,0,0,0.1), inset 0 1px 0 rgba(255,255,255,0.2);
}

/* Positioning */
.absolute { position: absolute; top: 10px; right: 20px; bottom: 30px; left: 40px; z-index: 100; }
.relative { position: relative; top: 5px; left: 10px; }
.fixed { position: fixed; top: 0; left: 0; width: 100%; z-index: 1000; }
.sticky { position: sticky; top: 0; }

/* Display and visibility */
.hide { display: none; }
.invisible { visibility: hidden; }
.block { display: block; }
.inline { display: inline; }
.inline-block { display: inline-block; }
.flex { display: flex; }
.grid { display: grid; }

/* Flexbox */
.flex-container {
    display: flex;
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: center;
    align-content: stretch;
    gap: 10px 20px;
}
.flex-item {
    flex: 1 1 auto;
    flex-grow: 2;
    flex-shrink: 0;
    flex-basis: 200px;
    align-self: flex-end;
    order: -1;
}

/* Grid */
.grid-container {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    grid-template-rows: auto 1fr auto;
    grid-gap: 20px;
    grid-auto-flow: dense;
    grid-template-areas:
        "header header header"
        "sidebar main main"
        "footer footer footer";
}
.grid-item {
    grid-column: 1 / 3;
    grid-row: 2 / span 2;
    grid-area: main;
}

/* Typography */
.text {
    font-family: "Helvetica Neue", Arial, sans-serif;
    font-size: clamp(14px, 2vw, 18px);
    font-weight: 600;
    font-style: italic;
    font-variant: small-caps;
    line-height: 1.6;
    letter-spacing: 0.05em;
    word-spacing: 0.1em;
    text-align: justify;
    text-indent: 2em;
    text-transform: uppercase;
    text-decoration: underline wavy red;
    text-shadow: 2px 2px 4px rgba(0,0,0,0.5);
    white-space: nowrap;
    word-wrap: break-word;
    overflow-wrap: break-word;
    hyphens: auto;
}

/* Colors */
.colors {
    color: #f00;
    background-color: rgb(0, 255, 0);
    border-color: rgba(0, 0, 255, 0.5);
    outline-color: hsl(120, 100%, 50%);
    box-shadow: 0 0 10px hsla(240, 100%, 50%, 0.7);
}

/* Backgrounds */
.background {
    background-color: white;
    background-image: url("image.png"), linear-gradient(to bottom, red, blue);
    background-size: cover, contain;
    background-position: center, top left;
    background-repeat: no-repeat, repeat-x;
    background-attachment: fixed, scroll;
    background-origin: border-box;
    background-clip: padding-box;
}

/* Borders */
.borders {
    border-width: 1px 2px 3px 4px;
    border-style: solid dashed dotted double;
    border-color: red green blue yellow;
    border-radius: 50%;
    border-image: url("border.png") 30 round;
}

/* Transforms */
.transform {
    transform: translate(10px, 20px) rotate(45deg) scale(1.5) skew(10deg, 5deg);
    transform-origin: center center;
    transform-style: preserve-3d;
    perspective: 1000px;
    perspective-origin: 50% 50%;
}

/* Transitions and animations */
.transition {
    transition: all 0.3s ease-in-out 0.1s;
    transition-property: opacity, transform;
    transition-duration: 0.5s, 1s;
    transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
    transition-delay: 0s, 0.2s;
}

@keyframes slide {
    0% { transform: translateX(-100%); opacity: 0; }
    50% { transform: translateX(0); opacity: 1; }
    100% { transform: translateX(100%); opacity: 0; }
}

.animated {
    animation: slide 2s ease-in-out infinite;
    animation-delay: 0.5s;
    animation-direction: alternate;
    animation-fill-mode: forwards;
    animation-iteration-count: 3;
    animation-play-state: running;
}

/* Filters */
.filtered {
    filter: blur(5px) brightness(1.2) contrast(1.1) grayscale(0.5) hue-rotate(90deg) invert(0.2) opacity(0.9) saturate(1.5) sepia(0.3);
    backdrop-filter: blur(10px);
}

/* Media queries */
@media screen and (min-width: 768px) {
    .responsive { width: 80%; }
}
@media (min-width: 992px) and (max-width: 1199px) {
    .responsive { width: 70%; }
}
@media (orientation: landscape) {
    .landscape { display: block; }
}
@media print {
    .no-print { display: none; }
    body { color: black; background: white; }
}

/* Supports queries */
@supports (display: grid) {
    .grid-fallback { display: grid; }
}
@supports not (display: flex) {
    .flex-fallback { display: table; }
}

/* Custom properties */
:root {
    --primary: #007bff;
    --secondary: #6c757d;
    --spacing: 1rem;
    --border-radius: 0.25rem;
}
.component {
    color: var(--primary);
    margin: var(--spacing);
    border-radius: var(--border-radius);
}

/* Calc */
.calc {
    width: calc(100% - 40px);
    height: calc(100vh - 60px);
    padding: calc(1rem + 5px);
    margin: calc((100% - 960px) / 2);
}

/* Multiple columns */
.columns {
    column-count: 3;
    column-width: 200px;
    column-gap: 2em;
    column-rule: 1px solid #ccc;
    column-span: all;
}

/* Tables */
table {
    border-collapse: collapse;
    border-spacing: 0;
    table-layout: fixed;
    caption-side: bottom;
}

/* Lists */
ul {
    list-style-type: circle;
    list-style-position: inside;
    list-style-image: url("bullet.png");
}

/* Overflow */
.overflow {
    overflow: auto;
    overflow-x: scroll;
    overflow-y: hidden;
    text-overflow: ellipsis;
}

/* Cursor */
.pointer { cursor: pointer; }
.wait { cursor: wait; }
.help { cursor: help; }

/* User interaction */
.no-select { user-select: none; }
.no-pointer { pointer-events: none; }
.resizable { resize: both; }

/* Misc */
.misc {
    opacity: 0.8;
    z-index: 999;
    mix-blend-mode: multiply;
    will-change: transform, opacity;
    aspect-ratio: 16 / 9;
